import { test, expect } from '@playwright/test';

test.describe('Modal Dialog', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should not allow scrolling on the background when modal is open', async ({ page }) => {
    await page.getByRole('button', { name: /open modal/i }).click(); // Adjust the button role and name as necessary
    const body = await page.locator('body');

    const initialScrollY = await body.evaluate(el => el.scrollTop);
    await page.keyboard.press('ArrowDown'); // Simulate scrolling
    const afterScrollY = await body.evaluate(el => el.scrollTop);

    expect(afterScrollY).toBe(initialScrollY); // Ensure scroll position hasn't changed
  });

  test('should close the modal and allow scrolling again', async ({ page }) => {
    await page.getByRole('button', { name: /open modal/i }).click(); // Adjust the button role and name as necessary
    await page.getByRole('button', { name: /close modal/i }).click(); // Adjust the close button role and name as necessary

    const body = await page.locator('body');
    const initialScrollY = await body.evaluate(el => el.scrollTop);
    await page.keyboard.press('ArrowDown'); // Simulate scrolling
    const afterScrollY = await body.evaluate(el => el.scrollTop);

    expect(afterScrollY).toBeGreaterThan(initialScrollY); // Ensure scroll position has changed
  });
});
